function citationScore(cites: number[]): number {
  const n = cites.length, bucket = new Array<number>(n + 1).fill(0);
  for (const c of cites) bucket[Math.min(c, n)]++;
  let atLeast = 0;
  for (let h = n; h > 0; h--) {
    atLeast += bucket[h];
    if (atLeast >= h) return h;
  }
  return 0;
}

