        n = len(cites)
        bucket = [0] * (n + 1)
        for c in cites:
            bucket[min(c, n)] += 1
        at_least = 0
        for h in range(n, 0, -1):
            at_least += bucket[h]
            if at_least >= h:
                return h
        return 0

